import * as React from 'react';
// import Box from '@mui/material/Box'; // Removed unused import
import Container from '@mui/material/Container';
// import Grid from '@mui/material/Grid'; // Keep commented out unless needed
import Typography from '@mui/material/Typography';
import { VerticalTimeline, VerticalTimelineElement }  from 'react-vertical-timeline-component';
import 'react-vertical-timeline-component/style.min.css';
import WorkIcon from '@mui/icons-material/Work';
import CodeIcon from '@mui/icons-material/Code'; 
import { useTheme } from '@mui/material/styles';
import ScienceIcon from '@mui/icons-material/Science';

const workExperience = [
  {
    company: 'Commure',
    title: 'Software Engineering Intern',
    duration: 'June 2025-August 2025',
    description: [
      'Supported multiple major site launches by building out backend infrastructure',
      'Created SFTP-based document modification and export pipeline to integrate major sites\' native EHRs',
      'Built out support for inpatient and dental claim submissions, exposing our RCM product to more healthcare sectors',
      'Revamped calculating procedure charge amounts to reduce revenue-blocking tickets from operations'
    ],
    icon: <CodeIcon /> 
  },
  {
    company: 'Humana',
    title: 'Software Engineer Intern',
    duration: 'May 2024 - December 2024',
    description: [
      'Created database optimization SQL processes that archived and purged Epost data, increasing query speeds by up to 20%',
      'Set up Azure Key vault and created Spring Boot APIs to securely access external credentials throughout Epost microservices'
    ],
    icon: <CodeIcon />
  },
  {
    company: 'Querry-Simpson Institute for Bioelectronics',
    title: 'Software Engineer Intern',
    duration: 'October 2022 - August 2023',
    description: [
      'Refactored signal processing error handling with Rust to provide a research-friendly interface for dysphagia analysis',
      'Optimized data processing to efficiently graph only relevant data with Matplotlib'
    ],
    icon: <ScienceIcon /> 
  },
];

export default function Timeline() {
  const theme = useTheme();

  const contentStyle = {
    background: theme.palette.mode === 'dark' ? theme.palette.grey[900] : theme.palette.grey[100],
    color: theme.palette.text.primary,
    boxShadow: 'none',
    border: `1px solid ${theme.palette.divider}`,
    borderRadius: '8px'
  };

  const contentArrowStyle = {
    borderRight: `7px solid ${theme.palette.mode === 'dark' ? theme.palette.grey[900] : theme.palette.grey[100]}`
  };

  const iconStyle = {
    background: theme.palette.primary.main,
    color: theme.palette.primary.contrastText
  };

  return (
    <Container id="timeline" sx={{ py: { xs: 8, sm: 10 }, width: '100%' }}> 
      <Typography component="h2" variant="h2" color="text.primary" sx={{ pb: 2 }}>
        Work Experience
      </Typography>
      <VerticalTimeline lineColor={theme.palette.divider}> 
        {workExperience.map((job, index) => (
          <VerticalTimelineElement
            key={index}
            className="vertical-timeline-element--work"
            contentStyle={contentStyle}
            contentArrowStyle={contentArrowStyle}
            date={job.duration}
            iconStyle={iconStyle}
            icon={job.icon || <WorkIcon />} 
          >
            <Typography variant="h6" component="h3" className="vertical-timeline-element-title">
              {job.title}
            </Typography>
            <Typography variant="subtitle1" component="h4" className="vertical-timeline-element-subtitle" sx={{ mb: 1 }}>
              {job.company}
            </Typography>
            <Typography variant="body2" component="div">
              <ul style={{ margin: 0, paddingLeft: '20px' }}>
                {Array.isArray(job.description) 
                  ? job.description.map((point, idx) => (
                      <li key={idx} style={{ marginBottom: '4px' }}>
                        {point}
                      </li>
                    ))
                  : <li>{job.description}</li>
                }
              </ul>
            </Typography>
          </VerticalTimelineElement>
        ))}
      </VerticalTimeline>
    </Container>
  );
}
